PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migration(version INTEGER PRIMARY KEY, name TEXT NOT NULL, sha256 TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS dataset_release(release_id TEXT PRIMARY KEY,label TEXT NOT NULL,imported_at TEXT NOT NULL,source_manifest_sha256 TEXT NOT NULL,notes TEXT);
CREATE TABLE IF NOT EXISTS school(roll TEXT PRIMARY KEY,name TEXT NOT NULL,roster_status TEXT,geographic_scope TEXT,website_url TEXT);
CREATE TABLE IF NOT EXISTS raw_record(raw_id TEXT PRIMARY KEY,release_id TEXT NOT NULL REFERENCES dataset_release, dataset TEXT NOT NULL,record_key TEXT NOT NULL,payload_json TEXT NOT NULL,payload_sha256 TEXT NOT NULL,normalization_status TEXT NOT NULL,exclusion_reason TEXT,UNIQUE(release_id,dataset,record_key));
CREATE TABLE IF NOT EXISTS import_reconciliation(release_id TEXT REFERENCES dataset_release,dataset TEXT,expected_rows INTEGER NOT NULL,raw_rows INTEGER NOT NULL,normalized_rows INTEGER NOT NULL,excluded_rows INTEGER NOT NULL,PRIMARY KEY(release_id,dataset));
CREATE TABLE IF NOT EXISTS source(source_id TEXT PRIMARY KEY,original_url TEXT NOT NULL,domain TEXT,source_kind TEXT NOT NULL,UNIQUE(original_url,source_kind));
CREATE TABLE IF NOT EXISTS school_identity(identity_id TEXT PRIMARY KEY,roll TEXT NOT NULL REFERENCES school,name TEXT NOT NULL,identity_type TEXT NOT NULL,valid_from TEXT,valid_to TEXT,source_id TEXT REFERENCES source,raw_id TEXT REFERENCES raw_record,quality TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS school_relation(relation_id TEXT PRIMARY KEY,predecessor_roll TEXT NOT NULL REFERENCES school,successor_roll TEXT NOT NULL REFERENCES school,relationship TEXT NOT NULL,effective_date TEXT,date_precision TEXT,source_id TEXT REFERENCES source,evidence_excerpt TEXT NOT NULL,raw_id TEXT REFERENCES raw_record);
CREATE TABLE IF NOT EXISTS school_metadata(metadata_id TEXT PRIMARY KEY,roll TEXT NOT NULL REFERENCES school,attribute TEXT NOT NULL,value_text TEXT NOT NULL,as_of TEXT,source_id TEXT REFERENCES source,raw_id TEXT REFERENCES raw_record,quality TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS school_location(location_id TEXT PRIMARY KEY,roll TEXT NOT NULL REFERENCES school,address TEXT,eircode TEXT,latitude REAL,longitude REAL,coordinate_crs TEXT NOT NULL DEFAULT 'EPSG:4326',as_of TEXT,as_of_precision TEXT,source_id TEXT REFERENCES source,raw_id TEXT REFERENCES raw_record,boundary_caveat TEXT NOT NULL,CHECK(latitude IS NULL OR latitude BETWEEN -90 AND 90),CHECK(longitude IS NULL OR longitude BETWEEN -180 AND 180));
CREATE TABLE IF NOT EXISTS document(document_id TEXT PRIMARY KEY,roll TEXT NOT NULL REFERENCES school,payload_sha256 TEXT,identity_key TEXT NOT NULL,media_type TEXT,identity_quality TEXT NOT NULL,UNIQUE(roll,identity_key));
CREATE TABLE IF NOT EXISTS document_source(document_id TEXT REFERENCES document,source_id TEXT REFERENCES source,PRIMARY KEY(document_id,source_id));
CREATE TABLE IF NOT EXISTS retrieval(retrieval_id TEXT PRIMARY KEY,document_id TEXT REFERENCES document,source_id TEXT NOT NULL REFERENCES source,retrieval_url TEXT NOT NULL,retrieval_kind TEXT NOT NULL,retrieved_at TEXT,http_status INTEGER,payload_sha256 TEXT,local_payload_path TEXT,archive_capture_timestamp TEXT,archive_capture_time_dublin TEXT,memento_datetime_header TEXT,body_verified INTEGER NOT NULL DEFAULT 0,notes TEXT);
CREATE TABLE IF NOT EXISTS notice(notice_id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES document,title_school_year TEXT,publication_time TEXT,publication_precision TEXT,notice_type TEXT NOT NULL DEFAULT 'annual_admission_notice',identity_verified INTEGER NOT NULL,UNIQUE(document_id,title_school_year));
CREATE TABLE IF NOT EXISTS cohort(cohort_id TEXT PRIMARY KEY,roll TEXT NOT NULL REFERENCES school,source_label TEXT NOT NULL,intake_kind TEXT NOT NULL,special_needs_label TEXT,scope_confirmed INTEGER NOT NULL,UNIQUE(roll,source_label));
CREATE TABLE IF NOT EXISTS school_period(period_id TEXT PRIMARY KEY,roll TEXT NOT NULL REFERENCES school,academic_year TEXT,year_start INTEGER,cohort_id TEXT NOT NULL REFERENCES cohort,UNIQUE(roll,academic_year,cohort_id));
CREATE TABLE IF NOT EXISTS observation_group(group_id TEXT PRIMARY KEY,notice_id TEXT NOT NULL REFERENCES notice,period_id TEXT NOT NULL REFERENCES school_period,phase TEXT NOT NULL,table_scope TEXT NOT NULL,as_of TEXT,year_status TEXT NOT NULL,cohort_matched INTEGER NOT NULL,quality TEXT NOT NULL,preferred_source_rank INTEGER NOT NULL DEFAULT 0,review_notes TEXT,definition_era TEXT NOT NULL,UNIQUE(notice_id,period_id,phase,table_scope));
CREATE TABLE IF NOT EXISTS metric_definition(metric_code TEXT PRIMARY KEY,label TEXT NOT NULL,definition TEXT NOT NULL,unit TEXT NOT NULL DEFAULT 'count');
CREATE TABLE IF NOT EXISTS observation(observation_id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES observation_group,metric_code TEXT NOT NULL REFERENCES metric_definition,value_integer INTEGER,value_status TEXT NOT NULL,definition_qualifier TEXT NOT NULL DEFAULT '',as_of TEXT,quality TEXT NOT NULL,CHECK(value_integer IS NULL OR value_integer>=0),CHECK((value_status='observed' AND value_integer IS NOT NULL) OR (value_status<>'observed' AND value_integer IS NULL)));
CREATE TABLE IF NOT EXISTS evidence(evidence_id TEXT PRIMARY KEY,document_id TEXT REFERENCES document,source_id TEXT REFERENCES source,source_field TEXT,source_value_json TEXT,page INTEGER,line_start INTEGER,line_end INTEGER,excerpt TEXT NOT NULL,source_payload_sha256 TEXT,text_file TEXT,text_file_sha256 TEXT,method TEXT,verified_excerpt INTEGER NOT NULL,year_evidence INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS observation_evidence(observation_id TEXT REFERENCES observation,evidence_id TEXT REFERENCES evidence,PRIMARY KEY(observation_id,evidence_id));
CREATE TABLE IF NOT EXISTS observation_lineage(observation_id TEXT REFERENCES observation,raw_id TEXT REFERENCES raw_record,source_field TEXT NOT NULL,PRIMARY KEY(observation_id,raw_id,source_field));
CREATE TABLE IF NOT EXISTS group_lineage(group_id TEXT REFERENCES observation_group,raw_id TEXT REFERENCES raw_record,PRIMARY KEY(group_id,raw_id));
CREATE TABLE IF NOT EXISTS collection_attempt(attempt_id TEXT PRIMARY KEY,roll TEXT REFERENCES school,source_id TEXT REFERENCES source,method TEXT NOT NULL,attempted_at TEXT,status TEXT NOT NULL,exact_status TEXT,query_text TEXT,requested_from TEXT,requested_to TEXT,coverage_limit TEXT,raw_id TEXT REFERENCES raw_record,details_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS coverage(coverage_id TEXT PRIMARY KEY,roll TEXT NOT NULL REFERENCES school,academic_year TEXT,coverage_dimension TEXT NOT NULL,status TEXT NOT NULL,source_id TEXT REFERENCES source,as_of TEXT,scope_limit TEXT NOT NULL,raw_id TEXT REFERENCES raw_record);
CREATE TABLE IF NOT EXISTS work_queue(task_id TEXT PRIMARY KEY,roll TEXT REFERENCES school,stage TEXT NOT NULL,source_url TEXT,document_id TEXT REFERENCES document,status TEXT NOT NULL,priority INTEGER NOT NULL,checkpoint_json TEXT NOT NULL,updated_at TEXT,UNIQUE(roll,stage,source_url));
CREATE TABLE IF NOT EXISTS geographic_area(area_id TEXT PRIMARY KEY,area_type TEXT NOT NULL,official_code TEXT,boundary_version TEXT,valid_from TEXT,valid_to TEXT,source_id TEXT REFERENCES source,geometry_wkt TEXT);
CREATE TABLE IF NOT EXISTS external_dataset(dataset_id TEXT PRIMARY KEY,name TEXT NOT NULL,provider TEXT NOT NULL,source_id TEXT REFERENCES source,definition TEXT NOT NULL,unit TEXT NOT NULL,release_time TEXT);
CREATE TABLE IF NOT EXISTS geographic_time_observation(geo_observation_id TEXT PRIMARY KEY,dataset_id TEXT NOT NULL REFERENCES external_dataset,area_id TEXT REFERENCES geographic_area,metric TEXT NOT NULL,period_start TEXT,period_end TEXT,age_min INTEGER,age_max INTEGER,value_numeric REAL,unit TEXT NOT NULL,source_id TEXT REFERENCES source,quality TEXT NOT NULL,notes TEXT);
CREATE TABLE IF NOT EXISTS development_inspection(inspection_id TEXT PRIMARY KEY,area_id TEXT REFERENCES geographic_area,development_public_id TEXT,inspection_date TEXT,status TEXT,aggregate_units INTEGER,source_id TEXT REFERENCES source,metadata_json TEXT);
CREATE INDEX IF NOT EXISTS idx_observation_group ON observation(group_id,metric_code);
CREATE INDEX IF NOT EXISTS idx_period_school_year ON school_period(roll,year_start,cohort_id);
CREATE INDEX IF NOT EXISTS idx_evidence_hash ON evidence(source_payload_sha256);
CREATE INDEX IF NOT EXISTS idx_attempt_school ON collection_attempt(roll,method,status);
CREATE INDEX IF NOT EXISTS idx_queue_status ON work_queue(stage,status,priority);

CREATE TABLE IF NOT EXISTS notice_title_assertion(assertion_id TEXT PRIMARY KEY,notice_id TEXT NOT NULL REFERENCES notice,title_school_year TEXT NOT NULL,raw_id TEXT REFERENCES raw_record);
